const lesson5BTNC=[{"file":"Q2B5.NC1.MP3","title":"Nâng cao 1","key":["B","E","A","C","D"],"transcript":["我这个周末日程排满了，恐怕没时间见面了。","我们约在星巴克见面吧，下午三点怎么样？","抱歉，我那天要飞去北京，下次吧。","我正在网上看机票，打算下个月去旅行。","星期六上午我打算在家大扫除。"],"questions":[["他这个周末有时间见面吗？",["有很多时间","恐怕没有时间","只有上午有时间"],1],["建议下午几点见面？",["三点","四点","五点"],0],["他那天要飞去哪里？",["上海","西安","北京"],2],["他正在网上看什么？",["衣服","机票","课本"],1],["他星期六上午打算做什么？",["旅行","看电影","在家大扫除"],2]]},{"file":"Q2B5.NC2.MP3","title":"Nâng cao 2","key":["E","C","B","D","A"],"transcript":["女：你晚上有空吗？我们几个朋友想一起玩。\n男：好啊，我七点以后都有空，在哪儿见面？","男：电影七点开始，我们六点四十五在电影院门口见，好吗？\n女：没问题，我会准时到的。","女：你头发长了，该去剪剪了。\n男：是啊，我打算周六上午去理发店。","男：下周一有考试，我们周末一起复习吧。\n女：好主意，星期天下午去图书馆怎么样？","女：冰箱里没什么吃的了，我们得去一趟超市。\n男：那就明天下午去吧，我开车载你。"],"questions":[["他晚上几点以后有空？",["六点","七点","八点"],1],["他们约几点在电影院门口见？",["六点四十五","七点","七点十五"],0],["他打算什么时候去理发店？",["周五晚上","周日下午","周六上午"],2],["他们打算在哪里复习？",["咖啡馆","图书馆","电影院"],1],["他们打算什么时候去超市？",["今天上午","明天上午","明天下午"],2]]},{"file":"Q2B5.NC3.MP3","title":"Nâng cao 3","key":["B","B","C","A","B"],"transcript":["男：阿芳，你周末有什么计划吗？\n女：周六我要陪妈妈去医院复查。周日还没安排。","男：下周五晚上公司有年会，你能参加吗？\n女：我看看，那晚我约了牙医，可能去不了。","男：假期你打算去哪儿玩？\n女：我打算先去北京，然后坐高铁去西安。","男：这个项目下周三必须完成，我们周末需要加班。\n女：周六我可以，但周日我要给我奶奶过生日。","男：你一般怎么安排你的业余时间？\n女：我周二和周四去健身，周末会看一部电影或者读一本书。"],"questions":[["阿芳周六要陪谁去医院？",["爸爸","妈妈","奶奶"],1],["她为什么可能不能参加年会？",["要旅行","要加班","约了牙医"],2],["她假期先去哪里？",["北京","西安","上海"],0],["她周日要做什么？",["加班","给奶奶过生日","去医院"],1],["她一般星期几去健身？",["周一和周三","周六和周日","周二和周四"],2]]}];
